app.delete('/users/:userId/addresses/:addressId', async (request, reply) => {
  const paramsSchema = z.object({
    userId: z.string().min(2),
    addressId: z.coerce.number().int().positive(),
  });

  const { userId, addressId } = paramsSchema.parse(request.params);
  resolveAuthenticatedUserId(request, userId);

  const deleted = await db.query(
    `
      DELETE FROM user_addresses
      WHERE id = $1 AND user_id = $2
      RETURNING id
    `,
    [addressId, userId]
  );

  if (!deleted.rowCount) {
    reply.code(404);
    return { ok: false, error: 'Address not found' };
  }

  const defaultExists = await db.query<{ exists: boolean }>(
    `
      SELECT EXISTS (
        SELECT 1 FROM user_addresses
        WHERE user_id = $1 AND is_default = TRUE
      ) AS exists
    `,
    [userId]
  );

  if (!defaultExists.rows[0]?.exists) {
    await db.query(
      `
        UPDATE user_addresses
        SET is_default = TRUE, updated_at = NOW()
        WHERE id = (
          SELECT id FROM user_addresses
          WHERE user_id = $1
          ORDER BY updated_at DESC
          LIMIT 1
        )
      `,
      [userId]
    );
  }

  return { ok: true };
});

function requireStripeMobilePaymentConfiguration(reply: FastifyReply): {
  stripeClient: Stripe;
  publishableKey: string;
} | null {
  if (!stripe || !config.stripePublishableKey) {
    reply.code(503);
    return null;
  }

  return {
    stripeClient: stripe,
    publishableKey: config.stripePublishableKey,
  };
}

