// â”€â”€ Payout schedule configuration â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
app.put('/users/:userId/payout-schedule', async (request, reply) => {
  const paramsSchema = z.object({ userId: z.string().min(2) });
  const { userId } = paramsSchema.parse(request.params);
  resolveAuthenticatedUserId(request, userId);

  const bodySchema = z.object({
    payoutAccountId: z.coerce.number().int().positive(),
    schedule: z.enum(['on_demand', 'weekly', 'biweekly', 'monthly']),
    payoutDayOfWeek: z.coerce.number().int().min(0).max(6).optional(),
    minimumGbp: z.number().min(0).max(10000).optional(),
  });
  const payload = bodySchema.parse(request.body ?? {});

  const result = await db.query<{ user_id: string }>(
    'SELECT user_id FROM payout_accounts WHERE id = $1 AND user_id = $2 LIMIT 1',
    [payload.payoutAccountId, userId]
  );
  if (!result.rowCount) {
    reply.code(404);
    return { ok: false, error: 'Payout account not found for this user' };
  }

  // Compute next scheduled payout time.
  let nextScheduledPayoutAt: string | null = null;
  if (payload.schedule !== 'on_demand') {
    const now = new Date();
    const dayOfWeek = payload.payoutDayOfWeek ?? 1; // Default Monday
    const targetDay = dayOfWeek;
    const currentDay = now.getDay();
    let daysUntil = (targetDay - currentDay + 7) % 7;
    if (daysUntil === 0) daysUntil = 7; // Next week, not today
    if (payload.schedule === 'biweekly') daysUntil += 7;
    if (payload.schedule === 'monthly') {
      // Next month on the target day-of-week's first occurrence
      daysUntil = (targetDay - currentDay + 7) % 7;
      const nextDate = new Date(now);
      nextDate.setDate(now.getDate() + daysUntil);
      nextDate.setMonth(nextDate.getMonth() + 1);
      nextScheduledPayoutAt = nextDate.toISOString();
    } else {
      const nextDate = new Date(now);
      nextDate.setDate(now.getDate() + daysUntil);
      nextDate.setHours(9, 0, 0, 0); // 9 AM UTC
      nextScheduledPayoutAt = nextDate.toISOString();
    }
  }

  await db.query(
    `UPDATE payout_accounts
     SET payout_schedule = $3,
         payout_day_of_week = $4,
         payout_minimum_gbp = $5,
         next_scheduled_payout_at = $6,
         updated_at = NOW()
     WHERE id = $1 AND user_id = $2`,
    [
      payload.payoutAccountId,
      userId,
      payload.schedule,
      payload.payoutDayOfWeek ?? null,
      payload.minimumGbp ?? config.payoutDefaultMinimumGbp,
      nextScheduledPayoutAt,
    ]
  );

  return {
    ok: true,
    payoutAccountId: payload.payoutAccountId,
    schedule: payload.schedule,
    nextScheduledPayoutAt,
  };
});

// â”€â”€ Payout schedule sweep â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Batch-creates payout_requests for sellers with scheduled payouts whose
// available balance exceeds their minimum. Called by a daily cron.
app.post('/ops/payouts/schedule-sweep', async (request, reply) => {
  const securityAdminError = ensureSecurityAdminAccess(request, reply);
  if (securityAdminError) {
    return securityAdminError;
  }

  if (!(await paymentTablesAvailable(db))) {
    reply.code(503);
    return {
      ok: false,
      error: 'Payment settlement tables are unavailable. Run migrations first.',
    };
  }

  const payoutPauseState = await getPayoutPauseState();
  if (payoutPauseState.paused) {
    reply.code(503);
    return {
      ok: false,
      error: 'Payouts temporarily paused for reconciliation review.',
    };
  }

  // Find payout accounts with a scheduled payout due.
  const dueAccounts = await db.query<{
    id: number;
    user_id: string;
    currency: string;
    payout_minimum_gbp: string;
  }>(
    `
      SELECT id, user_id, currency, payout_minimum_gbp::text
      FROM payout_accounts
      WHERE status = 'active'
        AND payout_schedule != 'on_demand'
        AND next_scheduled_payout_at IS NOT NULL
        AND next_scheduled_payout_at <= NOW()
      ORDER BY next_scheduled_payout_at ASC
      LIMIT 200
    `
  );

  const created: Array<{ userId: string; payoutAccountId: number; amountGbp: number }> = [];

  for (const account of dueAccounts.rows) {
    const minimumGbp = Number(account.payout_minimum_gbp) || config.payoutDefaultMinimumGbp;

    // Sum available seller_payable balance (net: credits minus debits for
    // payouts, reserve holds, and refund reversals).
    const balanceResult = await db.query<{ available_gbp: string }>(
      `
        SELECT COALESCE(SUM(
          CASE WHEN direction = 'credit' THEN amount_gbp ELSE -amount_gbp END
        ), 0)::text AS available_gbp
        FROM ledger_entries
        WHERE account_id = (
          SELECT id FROM ledger_accounts
          WHERE owner_type = 'user' AND owner_id = $1 AND account_code = 'seller_payable'
          LIMIT 1
        )
        AND created_at <= NOW()
      `,
      [account.user_id]
    );
    const availableGbp = Number(balanceResult.rows[0]?.available_gbp ?? '0');

    if (availableGbp < minimumGbp) {
      // Reschedule for next cycle.
      await db.query(
        `UPDATE payout_accounts SET next_scheduled_payout_at = NULL WHERE id = $1`,
        [account.id]
      );
      continue;
    }

    // Create a payout request for the available balance.
    const requestId = createRuntimeId('po');
    try {
      await db.query(
        `INSERT INTO payout_requests (id, user_id, payout_account_id, amount_gbp, amount_currency, status, idempotency_key, request_hash, metadata, created_at, updated_at)
         VALUES ($1, $2, $3, $4, $5, 'requested', $6, $7, $8::jsonb, NOW(), NOW())`,
        [
          requestId,
          account.user_id,
          account.id,
          availableGbp,
          account.currency,
          `sched_${account.id}_${new Date().toISOString().slice(0, 10)}`,
          `sched_${account.id}_${new Date().toISOString().slice(0, 10)}`,
          toJsonString({ source: 'schedule_sweep' }),
        ]
      );
      created.push({
        userId: account.user_id,
        payoutAccountId: account.id,
        amountGbp: availableGbp,
      });
    } catch (error) {
      request.log.error({ err: error, userId: account.user_id }, 'Scheduled payout creation failed');
    }

    // Clear the next scheduled payout time.
    await db.query(
      `UPDATE payout_accounts SET next_scheduled_payout_at = NULL, updated_at = NOW() WHERE id = $1`,
      [account.id]
    );
  }

  return {
    ok: true,
    createdCount: created.length,
    created,
  };
});

// â”€â”€ Reserve release sweep â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Releases rolling reserve holds whose holding period has expired.
app.post('/ops/payouts/reserve-release-sweep', async (request, reply) => {
  const securityAdminError = ensureSecurityAdminAccess(request, reply);
  if (securityAdminError) {
    return securityAdminError;
  }

  if (!(await paymentTablesAvailable(db))) {
    reply.code(503);
    return {
      ok: false,
      error: 'Payment settlement tables are unavailable. Run migrations first.',
    };
  }

  const dueHolds = await db.query<{
    id: number;
    user_id: string;
    order_id: string;
    held_amount_gbp: string;
  }>(
    `
      SELECT id, user_id, order_id, held_amount_gbp::text
      FROM payout_reserve_holds
      WHERE released_at IS NULL
        AND release_eligible_at <= NOW()
      ORDER BY release_eligible_at ASC
      LIMIT 200
    `
  );

  const released: Array<{ holdId: number; userId: string; amountGbp: number }> = [];

  for (const hold of dueHolds.rows) {
    const client = await db.connect();
    try {
      await client.query('BEGIN');

      // Credit the held amount back to seller_payable.
      const sellerPayableAccountId = await ensureLedgerAccount(
        client,
        'user',
        hold.user_id,
        'seller_payable'
      );
      const reserveAccountId = await ensureLedgerAccount(
        client,
        'platform',
        'platform',
        'reserve_hold'
      );

      const heldAmount = Number(hold.held_amount_gbp);
      await appendLedgerEntry(client, {
        accountId: reserveAccountId,
        counterpartyAccountId: sellerPayableAccountId,
        direction: 'debit',
        amountGbp: heldAmount,
        sourceType: 'reserve_release',
        sourceId: String(hold.id),
        lineType: 'reserve_release',
        metadata: { orderId: hold.order_id, holdId: hold.id },
      });
      await appendLedgerEntry(client, {
        accountId: sellerPayableAccountId,
        counterpartyAccountId: reserveAccountId,
        direction: 'credit',
        amountGbp: heldAmount,
        sourceType: 'reserve_release',
        sourceId: String(hold.id),
        lineType: 'reserve_release',
        metadata: { orderId: hold.order_id, holdId: hold.id },
      });

      await client.query(
        `UPDATE payout_reserve_holds SET released_at = NOW() WHERE id = $1`,
        [hold.id]
      );

      await client.query('COMMIT');
      released.push({
        holdId: Number(hold.id),
        userId: hold.user_id,
        amountGbp: heldAmount,
      });
    } catch (error) {
      await client.query('ROLLBACK');
      request.log.error({ err: error, holdId: hold.id }, 'Reserve release failed');
    } finally {
      client.release();
    }
  }

  return {
    ok: true,
    releasedCount: released.length,
    released,
  };
});

// Stripe Connect Onboarding Endpoints
app.post('/users/:userId/stripe-connect/account', async (request, reply) => {
  const paramsSchema = z.object({ userId: z.string().min(2) });
  const { userId } = paramsSchema.parse(request.params);
  resolveAuthenticatedUserId(request, userId);

  if (!stripe) {
    reply.code(503);
    return {
      ok: false,
      error: 'Stripe is not configured. Contact support.',
    };
  }

  // Check if user already has a Connect account
  const existingAccount = await db.query<{ id: number }>(
    'SELECT id FROM stripe_connect_accounts WHERE user_id = $1 LIMIT 1',
    [userId]
  );

  if (existingAccount.rowCount && existingAccount.rowCount > 0) {
    reply.code(409);
    return {
      ok: false,
      error: 'Stripe Connect account already exists for this user',
    };
  }

  try {
    // Create Stripe Connect account
    const account = await stripe.accounts.create(
      {
        type: 'standard',
        metadata: {
          userId,
          platform: 'thryftverse',
        },
      },
      { idempotencyKey: `connect:${userId}` }
    );

    // Store account reference
    await db.query(
      `
        INSERT INTO stripe_connect_accounts (
          user_id,
          stripe_account_id,
          status,
          charges_enabled,
          payouts_enabled
        )
        VALUES ($1, $2, $3, $4, $5)
      `,
      [userId, account.id, 'pending', false, false]
    );

    return {
      ok: true,
      stripeAccountId: account.id,
      status: 'pending',
    };
  } catch (error) {
    app.log.error({ err: error, userId }, 'Failed to create Stripe Connect account');
    reply.code(500);
    return {
      ok: false,
      error: 'Failed to create Stripe Connect account',
    };
  }
});

app.post('/users/:userId/stripe-connect/onboarding-link', async (request, reply) => {
  const paramsSchema = z.object({ userId: z.string().min(2) });
  const { userId } = paramsSchema.parse(request.params);
  resolveAuthenticatedUserId(request, userId);

  if (!stripe) {
    reply.code(503);
    return {
      ok: false,
      error: 'Stripe is not configured. Contact support.',
    };
  }

  const accountResult = await db.query<{ stripe_account_id: string }>(
    'SELECT stripe_account_id FROM stripe_connect_accounts WHERE user_id = $1 LIMIT 1',
    [userId]
  );

  if (!accountResult.rowCount || accountResult.rowCount === 0) {
    reply.code(404);
    return {
      ok: false,
      error: 'Stripe Connect account not found. Create account first.',
    };
  }

  const stripeAccountId = accountResult.rows[0].stripe_account_id;

  try {
    const accountLink = await stripe.accountLinks.create({
      account: stripeAccountId,
      refresh_url: `${config.appUrl}/stripe-connect/refresh?userId=${userId}`,
      return_url: `${config.appUrl}/stripe-connect/return?userId=${userId}`,
      type: 'account_onboarding',
    });

    // Update onboarding URL
    await db.query(
      'UPDATE stripe_connect_accounts SET onboarding_url = $1 WHERE user_id = $2',
      [accountLink.url, userId]
    );

    return {
      ok: true,
      onboardingUrl: accountLink.url,
    };
  } catch (error) {
    app.log.error({ err: error, userId, stripeAccountId }, 'Failed to create onboarding link');
    reply.code(500);
    return {
      ok: false,
      error: 'Failed to create onboarding link',
    };
  }
});

app.get('/users/:userId/stripe-connect/status', async (request, reply) => {
  const paramsSchema = z.object({ userId: z.string().min(2) });
  const { userId } = paramsSchema.parse(request.params);
  resolveAuthenticatedUserId(request, userId);

  if (!stripe) {
    reply.code(503);
    return {
      ok: false,
      error: 'Stripe is not configured. Contact support.',
    };
  }

  const accountResult = await db.query<{
    stripe_account_id: string;
    status: string;
    charges_enabled: boolean;
    payouts_enabled: boolean;
    onboarding_url: string;
  }>(
    `
      SELECT
        stripe_account_id,
        status,
        charges_enabled,
        payouts_enabled,
        onboarding_url
      FROM stripe_connect_accounts
      WHERE user_id = $1
      LIMIT 1
    `,
    [userId]
  );

  if (!accountResult.rowCount || accountResult.rowCount === 0) {
    return {
      ok: true,
      hasConnectAccount: false,
    };
  }

  const row = accountResult.rows[0];

  // Sync with Stripe to get latest status
  try {
    const stripeAccount = await stripe.accounts.retrieve(row.stripe_account_id);

    const updatedStatus = stripeAccount.charges_enabled && stripeAccount.payouts_enabled
      ? 'active'
      : 'requirements_due';

    // Update local status if changed
    if (updatedStatus !== row.status ||
        stripeAccount.charges_enabled !== row.charges_enabled ||
        stripeAccount.payouts_enabled !== row.payouts_enabled) {
      await db.query(
        `
          UPDATE stripe_connect_accounts
          SET status = $1,
              charges_enabled = $2,
              payouts_enabled = $3,
              updated_at = NOW()
          WHERE user_id = $4
        `,
        [updatedStatus, stripeAccount.charges_enabled, stripeAccount.payouts_enabled, userId]
      );
    }

    const complianceProfile = await getOrCreateComplianceProfile(db, userId);
    const capabilities = resolveCountryCapabilities({
      countryCode: complianceProfile.countryCode,
      residencyCountryCode: complianceProfile.residencyCountryCode,
    });
    const stripePayoutAllowed =
      isPayoutGatewayAllowed(capabilities, 'stripe_americas')
      && isPayoutCurrencyAllowed(capabilities, 'GBP');

    if (stripePayoutAllowed) {
      await db.query(
        `INSERT INTO payout_accounts (
           user_id,
           gateway_id,
           provider_account_ref,
           country_code,
           currency,
           status,
           metadata
         )
         VALUES ($1, 'stripe_americas', $2, $3, 'GBP', $4, $5::jsonb)
         ON CONFLICT (gateway_id, provider_account_ref)
         DO UPDATE SET
           country_code = EXCLUDED.country_code,
           currency = EXCLUDED.currency,
           status = EXCLUDED.status,
           metadata = payout_accounts.metadata || EXCLUDED.metadata,
           updated_at = NOW()
         WHERE payout_accounts.user_id = EXCLUDED.user_id`,
        [
          userId,
          row.stripe_account_id,
          stripeAccount.country?.toUpperCase()
            ?? capabilities.effectiveCountryCode,
          stripeAccount.payouts_enabled ? 'active' : 'pending',
          toJsonString({
            source: 'stripe_connect_status_sync',
            chargesEnabled: stripeAccount.charges_enabled,
            payoutsEnabled: stripeAccount.payouts_enabled,
            providerVerifiedAt: stripeAccount.payouts_enabled
              ? new Date().toISOString()
              : null,
          }),
        ]
      );
    }

    return {
      ok: true,
      hasConnectAccount: true,
      stripeAccountId: row.stripe_account_id,
      status: updatedStatus,
      chargesEnabled: stripeAccount.charges_enabled,
      payoutsEnabled: stripeAccount.payouts_enabled,
      onboardingUrl: row.onboarding_url,
      requirementsCurrentlyDue: stripeAccount.requirements?.currently_due ?? [],
      payoutPolicySupported: stripePayoutAllowed,
    };
  } catch (error) {
    app.log.error({ err: error, userId }, 'Failed to retrieve Stripe account status');
    // Return cached status on error
    return {
      ok: true,
      hasConnectAccount: true,
      stripeAccountId: row.stripe_account_id,
      status: row.status,
      chargesEnabled: row.charges_enabled,
      payoutsEnabled: row.payouts_enabled,
      onboardingUrl: row.onboarding_url,
      requirementsCurrentlyDue: [],
    };
  }
});

// â”€â”€ Multi-vendor KYC fallback (Persona/Onfido) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// When Stripe Identity is unavailable or fails, the system can fall back
// to Persona (US/CA) or Onfido (EU/UK) for identity verification.
app.post('/users/:userId/kyc-fallback', async (request, reply) => {
  const paramsSchema = z.object({ userId: z.string().min(2) });
  const { userId } = paramsSchema.parse(request.params);

  const authUser = (request as any).authUser;
  if (!authUser) {
    reply.code(401);
    return { ok: false, error: 'Unauthorized' };
  }
  if (authUser.userId !== userId && authUser.role !== 'admin') {
    reply.code(403);
    return { ok: false, error: 'Access denied' };
  }

  const bodySchema = z.object({
    provider: z.enum(['persona', 'onfido']),
    firstName: z.string().min(1).max(100).optional(),
    lastName: z.string().min(1).max(100).optional(),
    email: z.string().email().optional(),
    country: z.string().min(2).max(2),
    redirectUrl: z.string().url(),
  });
  const payload = bodySchema.parse(request.body);

  try {
    let result;
    if (payload.provider === 'persona') {
      result = await createPersonaInquiry({
        config: {
          personaApiKey: config.personaApiKey,
          personaTemplateId: config.personaTemplateId,
          personaApiBaseUrl: config.personaApiBaseUrl,
          onfidoApiKey: null,
          onfidoApiBaseUrl: '',
        },
        inquiry: {
          userId,
          provider: 'persona',
          firstName: payload.firstName,
          lastName: payload.lastName,
          email: payload.email,
          country: payload.country,
          redirectUrl: payload.redirectUrl,
        },
      });
    } else {
      result = await createOnfidoApplicant({
        config: {
          personaApiKey: null,
          personaTemplateId: null,
          personaApiBaseUrl: '',
          onfidoApiKey: config.onfidoApiKey,
          onfidoApiBaseUrl: config.onfidoApiBaseUrl,
        },
        inquiry: {
          userId,
          provider: 'onfido',
          firstName: payload.firstName,
          lastName: payload.lastName,
          email: payload.email,
          country: payload.country,
          redirectUrl: payload.redirectUrl,
        },
      });
    }

    return {
      ok: true,
      provider: payload.provider,
      inquiryId: result.providerInquiryId,
      redirectUrl: result.redirectUrl,
      status: result.status,
    };
  } catch (error) {
    reply.code(502);
    return {
      ok: false,
      error: (error as Error).message,
    };
  }
});

app.get('/users/:userId/payout-requests', async (request, reply) => {
  const paramsSchema = z.object({ userId: z.string().min(2) });
  const querySchema = z.object({
    limit: z.coerce.number().int().min(1).max(200).default(60),
  });

  const { userId } = paramsSchema.parse(request.params);
  resolveAuthenticatedUserId(request, userId);
  const { limit } = querySchema.parse(request.query);

  if (!(await paymentTablesAvailable(db))) {
    reply.code(503);
    return {
      ok: false,
      error: 'Payment settlement tables are unavailable. Run migrations first.',
    };
  }

  const result = await db.query<PayoutRequestRow>(
    `
      SELECT
        id,
        user_id,
        payout_account_id,
        amount_gbp,
        amount_currency,
        amount_minor,
        currency_exponent,
        money_registry_version,
        money_conversion_trace,
        money_quarantined,
        status,
        provider_payout_ref,
        failure_reason,
        metadata,
        created_at,
        updated_at
      FROM payout_requests
      WHERE user_id = $1
      ORDER BY created_at DESC
      LIMIT $2
    `,
    [userId, limit]
  );

  return {
    ok: true,
    items: result.rows.map((row) => toPayoutRequestPayload(row)),
  };
});

