const shutdown = async () => {
  if (isShuttingDown) {
    return;
  }

  isShuttingDown = true;

  stopAuctionSweepScheduler();
  stopDomainOutboxScheduler();
  stopRetentionSweepScheduler();
  stopAnalyticsAggregationScheduler();
  stopPushReceiptReconciliationScheduler();
  stopScheduledPublicationSweepScheduler();
  stopPlatformReconciliationScheduler();
  stopPlatformRevenueSweepScheduler();
  stopOpsAlertingScheduler();
  stopOnezeReconciliationScheduler();
  stopOnezeDailyAttestationScheduler();
  stopOnezeFxSyncScheduler();
  stopOnezeAutoAdjustScheduler();

  try {
    await app.close();
  } catch (error) {
    app.log.error({ err: error }, 'Failed closing HTTP server');
  }

  try {
    await closeRealtimeConnections();
  } catch (error) {
    app.log.error({ err: error }, 'Failed closing realtime connections');
  }

  try {
    await closeBackgroundQueues();
  } catch (error) {
    app.log.error({ err: error }, 'Failed closing background queues');
  }

  try {
    await closeRedis();
  } catch (error) {
    app.log.error({ err: error }, 'Failed closing Redis client');
  }

  try {
    await closeDb();
  } catch (error) {
    app.log.error({ err: error }, 'Failed closing Postgres pool');
  }

  try {
    await shutdownTelemetry();
  } catch (error) {
    app.log.error({ err: error }, 'Failed shutting down telemetry');
  }
};

process.on('uncaughtException', (err) => {
  if (err.message === 'Connection is closed.') {
    logger.warn({ err: err.message }, '[uncaughtException] Redis connection closed (suppressed)');
    return;
  }
  logger.error({ err }, '[uncaughtException] Fatal');
  process.exit(1);
});

process.on('unhandledRejection', (reason) => {
  if (reason instanceof Error && reason.message === 'Connection is closed.') {
    logger.warn({ err: reason.message }, '[unhandledRejection] Redis connection closed (suppressed)');
    return;
  }
  logger.error({ reason }, '[unhandledRejection] Fatal â€” unhandled promise rejection');
  process.exit(1);
});

process.on('SIGINT', async () => {
  await shutdown();
  process.exit(0);
});

process.on('SIGTERM', async () => {
  await shutdown();
  process.exit(0);
});

void start();
